package main

import "embed"

// The icons are generated by tools/icongen in the main module
// (GOTOOLCHAIN=go1.26.9 go run ./tools/icongen from the repo root); do not
// edit them by hand.
//
//go:embed assets/icon.ico assets/icon-pending.ico assets/icon-pairing.ico assets/icon.png assets/icon-pending.png assets/icon-pairing.png
var assets embed.FS

// Icon is which tray icon to show.
type Icon int

const (
	IconPlain   Icon = iota // the rocket
	IconPending             // red badge: incoming offers are waiting
	IconPairing             // amber badge: a pairing window is open
)

// iconBytes returns the tray icon for goos: .ico on Windows (systray needs
// it there), PNG elsewhere.
func iconBytes(goos string, icon Icon) []byte {
	name := "assets/icon"
	switch icon {
	case IconPending:
		name += "-pending"
	case IconPairing:
		name += "-pairing"
	}
	if goos == "windows" {
		name += ".ico"
	} else {
		name += ".png"
	}
	b, err := assets.ReadFile(name)
	if err != nil {
		panic("rocket-tray: missing embedded icon " + name) // embed guarantees it
	}
	return b
}
